insert into fiche_versions (subject_id, version, content, published_at) values ('acs', 1, $fiche${"meta": {"id": "acs", "title": "Syndrome coronarien aigu : conduite à tenir", "motifs": [], "status": "published", "country": "DZ", "version": "1.0.0", "audience": ["urgences"], "language": "fr", "template": "urgence", "specialite": "Cardiovasculaire", "next_review_at": null, "last_reviewed_at": "2026-10-17"}, "scope": {"exclusions": [], "population": "Adulte avec suspicion de syndrome coronarien aigu (angor instable, infarctus avec ou sans sus-décalage ST)"}, "treat": {"do_not": [{"id": "sca-045", "refs": [], "text": "Pas d'oxygène systématique si SaO2 > 90 %.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3745, "quote": "Routine oxygen is not recommended in patients without hypoxaemia (SaO2 >90%).", "source_id": "esc-2023-sca"}], "strength": "à_éviter", "condition": null}, {"id": "sca-046", "refs": [], "text": "N'utilisez pas le soulagement par la trinitrine comme test diagnostique.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3744, "quote": "a reduction in chest pain after nitroglycerine administration can be misleading and is not recommended as a diagnostic manoeuvre.", "source_id": "esc-2023-sca"}], "strength": null, "condition": null}, {"id": "sca-043", "refs": [], "text": "Pas de prétraitement par inhibiteur du P2Y12 avant la coronarographie.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1030, "quote": "Chez les patients avec NSTE-SCA bénéficiant d'une coronarographie, le prétraitement par inhibiteur du P2Y12 n'est pas recommandé", "source_id": "rms-2024-sca"}], "strength": null, "condition": "SCA sans sus-décalage ST"}, {"id": "sca-044", "refs": [], "text": "Jamais de DAPT de moins d'un mois, ni de désescalade pendant le premier mois.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1030, "quote": "Une DAPT abrégée de moins d'un mois et une désescalade de la DAPT le premier mois ne sont jamais recommandées", "source_id": "rms-2024-sca"}], "strength": "à_éviter", "condition": null}, {"id": "sca-024", "refs": [], "text": "Pas de coronarographie en urgence.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1029, "quote": "pour les patients avec arrêt cardiaque réanimé sans sus-décalage du segment ST ni choc cardiogène, une coronarographie en urgence n'est pas indiquée", "source_id": "rms-2024-sca"}], "strength": null, "condition": "Arrêt cardiaque réanimé, sans sus-décalage ST ni choc cardiogène"}], "actions": [{"id": "sca-013", "refs": [], "text": "Donnez l'aspirine à tous les patients sans contre-indication, dès le diagnostic (dose ci-dessus).", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3758, "quote": "Aspirin is recommended for all patients without contraindications", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": null}, {"id": "sca-014", "refs": [], "text": "Débutez une anticoagulation parentérale dès le diagnostic.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3758, "quote": "Parenteral anticoagulation is recommended for all patients with ACS at the time of diagnosis.", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": null}, {"id": "sca-015", "refs": [], "text": "Oxygène seulement si SaO2 < 90 %.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3745, "quote": "Oxygen is recommended in patients with hypoxaemia (SaO2 <90%).", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": "SaO2 < 90 %"}, {"id": "sca-016", "refs": [], "text": "Soulagez la douleur par opioïdes IV.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3745, "quote": "Intravenous opioids should be considered to relieve pain.", "source_id": "esc-2023-sca"}], "strength": "modérée", "condition": null}, {"id": "sca-017", "refs": [], "text": "Un dérivé nitré sublingual peut soulager l'ischémie.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3744, "quote": "Sublingual nitrate may be helpful to relieve ischaemic symptoms.", "source_id": "esc-2023-sca"}], "strength": null, "condition": null}, {"id": "sca-030", "refs": [], "text": "Double antiagrégation (DAPT) pendant un an, puis aspirine seule : stratégie par défaut.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1030, "quote": "une DAPT d'un an, suivie d'aspirine seule reste la stratégie par défaut", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}, {"id": "sca-031", "refs": [], "text": "Inhibiteur puissant du P2Y12 : préférez le prasugrel.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1030, "quote": "Concernant le choix d'inhibiteur puissant du P2Y12 (prasugrel ou ticagrelor) chez les patients atteints d'un SCA, une préférence est donnée au prasugrel (classe IIa)", "source_id": "rms-2024-sca"}], "strength": "modérée", "condition": null}, {"id": "sca-032", "refs": [], "text": "Le prétraitement par inhibiteur du P2Y12 peut être envisagé.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1030, "quote": "Concernant le prétraitement par inhibiteur du récepteur P2Y12 (prasugrel, ticagrelor, ou clopidogrel) chez les patients atteints d'un STEMI et bénéficiant d'une angioplastie primaire", "source_id": "rms-2024-sca"}, {"page": 1030, "quote": "Le prétraitement est à présent rétrogradé à une classe IIb", "source_id": "rms-2024-sca"}], "strength": "faible", "condition": "STEMI, angioplastie primaire prévue"}, {"id": "sca-033", "refs": [], "text": "Envisagez le clopidogrel comme inhibiteur du P2Y12.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1027, "quote": "Chez les patients âgés, surtout en cas de risque hémorragique élevé, le clopidogrel comme inhibiteur du P2Y12 peut être considéré", "source_id": "rms-2024-sca"}], "strength": "faible", "condition": "Sujet âgé, surtout si risque hémorragique élevé"}, {"id": "sca-ad1", "refs": [], "text": "Ticagrelor, dose de charge : 2 comprimés de 90 mg.", "basis": "Seule présentation enregistrée en Algérie : comprimé de 90 mg (BRILIQUE, PLAXELOR) ; validé par le Dr Mounib Zaidi le 04/10/2026.", "origin": "adaptation_locale", "timing": null, "evidence": [], "strength": null, "condition": null}, {"id": "sca-ad2", "refs": [], "text": "Prasugrel, dose de charge : 60 mg = 6 comprimés de 10 mg (pas de comprimé de charge).", "basis": "Présentations enregistrées en Algérie : 5 et 10 mg (PERGUS) ; validé par le Dr Mounib Zaidi le 04/10/2026.", "origin": "adaptation_locale", "timing": null, "evidence": [], "strength": null, "condition": null}, {"id": "sca-034", "refs": [], "text": "Déjà sous hypolipémiant : intensifiez-le pendant l'hospitalisation.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1027, "quote": "L'intensification du traitement hypolipémiant pendant le séjour hospitalier du SCA chez les patients déjà sous traitement hypolipémiant avant l'admission est recommandée", "source_id": "rms-2024-sca"}], "strength": "forte", "condition": "Hypolipémiant avant l'admission"}, {"id": "sca-051", "refs": [], "text": "Statine à forte dose le plus tôt possible, quel que soit le LDL initial.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3787, "quote": "It is recommended that high-dose statin therapy is initiated or continued as early as possible, regardless of initial LDL-C values.", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": null}, {"id": "sca-053", "refs": [], "text": "Bêtabloquant si FEVG ≤ 40 %, avec ou sans symptômes d'insuffisance cardiaque.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3788, "quote": "Beta-blockers are recommended in ACS patients with LVEF ≤40% regardless of HF symptoms.", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": "FEVG ≤ 40 %"}], "medications": [{"id": "med-aspirine-charge", "inn": "acide acétylsalicylique", "dose": 150, "phase": "initiation", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Aspirin LD of 150–300 mg orally or 75–250 mg i.v. if oral ingestion is not possible", "source_id": "esc-2023-sca"}, {"page": 3758, "quote": "Aspirin is recommended for all patients without contraindications at an initial oral LD of 150–300 mg (or 75–250 mg i.v.)", "source_id": "esc-2023-sca"}], "max_dose": "300 mg", "strength": "forte", "condition": null, "dose_unit": "mg", "frequency": "dose de charge unique", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": "aspirine-charge", "contraindications": [], "local_availability": {"brands": ["ACEPRAL CARDIO", "ASPEC", "ASPICARD", "ASPINOVA", "ASPIRINE CARDIO", "KARDEGIC"], "status": "enregistre", "country": "DZ"}}, {"id": "med-aspirine-charge-iv", "inn": "acide acétylsalicylique", "dose": 75, "phase": "initiation", "route": "IV", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Aspirin LD of 150–300 mg orally or 75–250 mg i.v. if oral ingestion is not possible", "source_id": "esc-2023-sca"}], "max_dose": "250 mg", "strength": "forte", "condition": "Prise orale impossible", "dose_unit": "mg", "frequency": "dose de charge unique", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": "aspirine-charge", "contraindications": [], "local_availability": {"brands": ["ASPIGAL"], "status": "enregistre", "country": "DZ"}}, {"id": "med-aspirine-entretien", "inn": "acide acétylsalicylique", "dose": 75, "phase": "entretien", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "followed by oral MD of 75–100 mg o.d.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "MD, maintenance dose; o.d., once a day", "source_id": "esc-2023-sca"}], "max_dose": "100 mg", "strength": "forte", "condition": null, "dose_unit": "mg", "frequency": "1 fois par jour", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": null, "contraindications": [], "local_availability": {"brands": ["ACEPRAL CARDIO", "ASPEC", "ASPICARD", "ASPINOVA", "ASPIRINE CARDIO", "KARDEGIC"], "status": "enregistre", "country": "DZ"}}, {"id": "med-ticagrelor-charge", "inn": "ticagrelor", "dose": 180, "phase": "initiation", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Ticagrelor LD of 180 mg orally, followed by an MD of 90 mg b.i.d.", "source_id": "esc-2023-sca"}], "max_dose": null, "strength": null, "condition": null, "dose_unit": "mg", "frequency": "dose de charge unique", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": "p2y12-charge", "contraindications": [], "local_availability": {"brands": ["BRILIQUE", "PLAXELOR"], "status": "enregistre", "country": "DZ"}}, {"id": "med-prasugrel-charge", "inn": "prasugrel", "dose": 60, "phase": "initiation", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Prasugrel LD of 60 mg orally, followed by an MD of 10 mg o.d.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "Prior stroke is a contraindication for prasugrel.", "source_id": "esc-2023-sca"}], "max_dose": null, "strength": null, "condition": null, "dose_unit": "mg", "frequency": "dose de charge unique", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": "p2y12-charge", "contraindications": ["Antécédent d'AVC"], "local_availability": {"brands": ["PERGUS"], "status": "enregistre", "country": "DZ"}}, {"id": "med-clopidogrel-charge", "inn": "clopidogrel", "dose": 300, "phase": "initiation", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Clopidogrel LD of 300–600 mg orally, followed by an MD of 75 mg o.d.", "source_id": "esc-2023-sca"}], "max_dose": "600 mg", "strength": null, "condition": null, "dose_unit": "mg", "frequency": "dose de charge unique", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": "p2y12-charge", "contraindications": [], "local_availability": {"brands": ["CLOPIDOGREL LDM", "CLOPIDOGREL NOVAGENERICS", "DAZIL", "PIDOGREL", "PLAVIX"], "status": "enregistre", "country": "DZ"}}, {"id": "med-ticagrelor-entretien", "inn": "ticagrelor", "dose": 90, "phase": "entretien", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Ticagrelor LD of 180 mg orally, followed by an MD of 90 mg b.i.d.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "b.i.d., bis in die (twice a day)", "source_id": "esc-2023-sca"}], "max_dose": null, "strength": null, "condition": null, "dose_unit": "mg", "frequency": "2 fois par jour", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": "p2y12-entretien", "contraindications": [], "local_availability": {"brands": ["BRILIQUE", "PLAXELOR"], "status": "enregistre", "country": "DZ"}}, {"id": "med-prasugrel-entretien", "inn": "prasugrel", "dose": 10, "phase": "entretien", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Prasugrel LD of 60 mg orally, followed by an MD of 10 mg o.d. In patients with body weight <60 kg, an MD of 5 mg o.d. is recommended.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "In patients aged ≥75 years, prasugrel should be used with caution, but a MD of 5 mg o.d. should be used if treatment is deemed necessary.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "Prior stroke is a contraindication for prasugrel.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "MD, maintenance dose; o.d., once a day", "source_id": "esc-2023-sca"}], "max_dose": null, "strength": null, "condition": null, "dose_unit": "mg", "frequency": "1 fois par jour", "dose_basis": "fixe", "prescriber": "officine", "adjustments": ["Poids < 60 kg : 5 mg 1 fois par jour", "Âge ≥ 75 ans : prudence ; 5 mg 1 fois par jour si nécessaire"], "alternative_group": "p2y12-entretien", "contraindications": ["Antécédent d'AVC"], "local_availability": {"brands": ["PERGUS"], "status": "enregistre", "country": "DZ"}}, {"id": "med-clopidogrel-entretien", "inn": "clopidogrel", "dose": 75, "phase": "entretien", "route": "orale", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "Clopidogrel LD of 300–600 mg orally, followed by an MD of 75 mg o.d.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "MD, maintenance dose; o.d., once a day", "source_id": "esc-2023-sca"}], "max_dose": null, "strength": null, "condition": null, "dose_unit": "mg", "frequency": "1 fois par jour", "dose_basis": "fixe", "prescriber": "officine", "adjustments": [], "alternative_group": "p2y12-entretien", "contraindications": [], "local_availability": {"brands": ["CLOPIDOGREL LDM", "CLOPIDOGREL NOVAGENERICS", "DAZIL", "PIDOGREL", "PLAVIX"], "status": "enregistre", "country": "DZ"}}, {"id": "med-hnf", "inn": "héparine non fractionnée", "dose": 70, "phase": "initiation", "route": "IV", "missing": [], "duration": null, "evidence": [{"page": 3751, "quote": "UFH Initial treatment: i.v. bolus 70–100 U/kg followed by i.v. infusion titrated to achieve an aPTT of 60–80 s.", "source_id": "esc-2023-sca"}], "max_dose": "100 UI/kg (bolus)", "strength": "forte", "condition": null, "dose_unit": "UI", "frequency": "bolus, puis perfusion IV adaptée pour un TCA de 60 à 80 s", "dose_basis": "par_kg", "prescriber": "officine", "adjustments": [], "alternative_group": "anticoagulant", "contraindications": [], "local_availability": {"brands": ["NEVPARIN"], "status": "enregistre", "country": "DZ"}}, {"id": "med-enoxaparine", "inn": "énoxaparine", "dose": 1, "phase": "initiation", "route": "sous-cutanée", "missing": [], "duration": "au moins 2 jours, jusqu'à stabilisation", "evidence": [{"page": 3751, "quote": "Enoxaparin Initial treatment: for treatment of ACS 1 mg/kg b.i.d. subcutaneously for a minimum of 2 days and continued until clinical stabilization.", "source_id": "esc-2023-sca"}, {"page": 3751, "quote": "In patients whose CrCl is below 30 mL per minute (by Cockcroft–Gault equation), the enoxaparin dosage should be reduced to 1 mg per kg o.d.", "source_id": "esc-2023-sca"}], "max_dose": null, "strength": "forte", "condition": null, "dose_unit": "mg", "frequency": "2 fois par jour", "dose_basis": "par_kg", "prescriber": "officine", "adjustments": ["Clairance < 30 mL/min : 1 mg/kg 1 fois par jour"], "alternative_group": "anticoagulant", "contraindications": [], "local_availability": {"brands": ["LOMOH-20", "LOMOH-40", "LOMOH-60", "LOMOH-80", "LOVENOX", "THERANOX", "VARENOX"], "status": "enregistre", "country": "DZ"}}]}, "advise": [], "assess": {"ask": [{"id": "sca-004", "refs": [], "text": "Recherchez les équivalents de douleur thoracique : dyspnée, douleur épigastrique, douleur du bras gauche ou droit, du cou ou de la mâchoire.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3735, "quote": "Chest pain-equivalent symptoms include dyspnoea, epigastric pain, and pain in the left or right arm or neck/jaw.", "source_id": "esc-2023-sca"}], "strength": null, "condition": null}, {"id": "sca-006", "refs": [], "text": "Classez la douleur : cardiaque, possiblement cardiaque ou probablement non cardiaque (ne dites plus « atypique »).", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3735, "quote": "Chest pain descriptors should be classified as cardiac, possibly cardiac, and likely non-cardiac.", "source_id": "esc-2023-sca"}], "strength": null, "condition": null}], "tests": [{"id": "sca-026", "refs": [], "text": "Dosez la troponine hypersensible à l'admission et à 1 h (ou à 0 et 2 h si impossible).", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1026, "quote": "à l'admission et à 1 heure (0/1 heure) ou, si ceci n'est pas faisable, à l'admission et à 2 heures (0/2 heures)", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}, {"id": "sca-027", "refs": [], "text": "Ni exclu ni confirmé : nouvelle troponine à 3 h, échocardiographie si nécessaire.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1026, "quote": "avec une mesure supplémentaire du taux de troponine à 3 heures et, si nécessaire, une échocardiographie", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}, {"id": "sca-028", "refs": [], "text": "Préférez le dosage en laboratoire central au test rapide.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1026, "quote": "Les troponines mesurées par tests automatisés dans des laboratoires centralisés sont toujours préférées aux tests « point of care »", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}], "examine": [{"id": "sca-007", "refs": [], "text": "Palpez tous les pouls, mesurez la PA au bras droit et au bras gauche, auscultez cœur et poumons, recherchez une insuffisance cardiaque ou un bas débit.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3737, "quote": "Focused physical examination should include checking for the presence of all major pulses, measurement of blood pressure in both arms, auscultation of the heart and lungs, and assessing for signs of HF or circulatory compromise.", "source_id": "esc-2023-sca"}], "strength": null, "condition": null}], "pathway": {"nodes": [{"id": "n1", "type": "decision", "items": [], "branches": [{"id": "n1-b1", "label": "Oui", "next_node_id": "n2"}, {"id": "n1-b2", "label": "Non", "next_node_id": "n5"}], "question": "Sus-décalage du segment ST (STEMI) ?"}, {"id": "n2", "type": "decision", "items": [], "branches": [{"id": "n2-b1", "label": "Oui", "next_node_id": "n3"}, {"id": "n2-b2", "label": "Non", "next_node_id": "n4"}], "question": "Angioplastie possible dans les 120 min ?"}, {"id": "n3", "type": "end", "items": [{"id": "sca-001", "refs": [], "text": "Coronarographie immédiate.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1027, "quote": "Pour les patients avec STEMI, une coronarographie immédiate est indiquée.", "source_id": "rms-2024-sca"}], "strength": "forte", "condition": null}, {"id": "sca-019", "refs": [], "text": "Revascularisation en moins de 60 min si le centre a une salle de cathétérisme, en moins de 90 min si le patient est transféré.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1027, "quote": "dans les 60 minutes si le patient est admis dans un centre avec salle de cathétérisme cardiaque, et en moins de 90 minutes si le patient est transféré depuis un autre centre", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}], "branches": [], "question": "STEMI, angioplastie possible"}, {"id": "n4", "type": "end", "items": [{"id": "sca-020", "refs": [], "text": "Faites la fibrinolyse, puis transférez vers un centre de cardiologie interventionnelle.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1027, "quote": "Si la revascularisation percutanée n'est pas possible dans les 120 minutes au moment du diagnostic, l'administration de fibrinolyse est indiquée", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}], "branches": [], "question": "STEMI, angioplastie impossible dans les 120 min"}, {"id": "n5", "type": "decision", "items": [], "branches": [{"id": "n5-b1", "label": "Très élevé", "next_node_id": "n6"}, {"id": "n5-b2", "label": "Élevé", "next_node_id": "n7"}, {"id": "n5-b3", "label": "Non élevé", "next_node_id": "n8"}], "question": "SCA sans sus-décalage ST : niveau de risque ?"}, {"id": "n6", "type": "end", "items": [{"id": "sca-021", "refs": [], "text": "Coronarographie immédiate.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1031, "quote": "à très haut risque (avec instabilité hémodynamique), une coronarographie immédiate est recommandée", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}], "branches": [], "question": "Risque très élevé"}, {"id": "n7", "type": "end", "items": [{"id": "sca-003", "refs": [], "text": "Coronarographie pendant l'hospitalisation, plus obligatoirement dans les 24 h.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1028, "quote": "une coronarographie est désormais recommandée au cours du séjour hospitalier mais pas obligatoirement dans les 24 heures après admission", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}], "branches": [], "question": "Risque élevé : NSTEMI avéré, GRACE > 140 ou modifications ECG dynamiques"}, {"id": "n8", "type": "end", "items": [{"id": "sca-023", "refs": [], "text": "Coronarographie sélective ou examen non invasif.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1028, "quote": "Une coronarographie sélective ou un examen non invasif sont recommandés pour la catégorie de risque « non élevé »", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}], "branches": [], "question": "Risque non élevé"}], "start_node_id": "n1"}}, "review": {"reviewer": "Mounib Zaidi", "change_log": [{"by": "Claude (conversion)", "date": "2026-10-17", "summary": "Conversion de la fiche v1 (schéma numéroté) en v1.1, citations vérifiées sur les PDF ESC 2023 et Revue Médicale Suisse 2024. Fourchettes de dose : borne basse en dose, borne haute en dose maximale. Retirés : fondaparinux (aucune présentation en Algérie), rivaroxaban 2,5 mg (aucune présentation 2,5 mg), ténectéplase (dose dans l'annexe en ligne seulement), coroscanner (changement de classe), choc avec atteinte pluritronculaire (hors audience), définitions."}, {"by": "Mounib Zaidi", "date": "2026-10-17", "summary": "Validation clinique et publication de la version v1.1."}], "reviewed_at": "2026-10-17", "clinical_approval": true, "unresolved_issues": []}, "red_box": {"signs": [{"id": "sca-005", "refs": [], "text": "Douleur thoracique prolongée (> 15 min) ou récidivante dans l'heure.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 3736, "quote": "red flag symptoms such as prolonged chest pain (>15 min) and/or recurrent pain within 1 h", "source_id": "esc-2023-sca"}], "strength": null, "condition": null}, {"id": "sca-009", "refs": [], "text": "Instabilité hémodynamique ou choc cardiogénique.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1027, "quote": "La catégorie de risque « très élevé » concerne toujours les patients avec instabilité hémodynamique ou choc cardiogénique", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}, {"id": "sca-010", "refs": [], "text": "Insuffisance cardiaque aiguë ischémique, arythmie menaçante, arrêt cardiaque, complication mécanique, modifications ECG dynamiques.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 1028, "quote": "une insuffisance cardiaque aiguë présumée secondaire à une ischémie myocardique en cours, des arythmies menaçant la vie, un arrêt cardiaque, des complications mécaniques et/ou des changements dynamiques récurrents de l'ECG", "source_id": "rms-2024-sca"}], "strength": null, "condition": null}], "actions": [{"id": "sca-011", "refs": [], "text": "Faites et interprétez un ECG 12 dérivations dès le premier contact : objectif < 10 min.", "basis": null, "origin": "source", "timing": "immediate", "evidence": [{"page": 3738, "quote": "Twelve-lead ECG recording and interpretation is recommended as soon as possible at the point of FMC, with a target of <10 min.", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": null}, {"id": "sca-012", "refs": [], "text": "Prenez les constantes vitales en même temps que l'ECG.", "basis": null, "origin": "source", "timing": "immediate", "evidence": [{"page": 3737, "quote": "Prompt assessment of vital signs is recommended at first medical contact (FMC), at the same time as acquisition of an initial ECG", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": null}, {"id": "sca-048", "refs": [], "text": "Monitorage ECG continu, défibrillateur à portée de main.", "basis": null, "origin": "source", "timing": "immediate", "evidence": [{"page": 3738, "quote": "Continuous ECG monitoring and the availability of defibrillator capacity is recommended as soon as possible in all patients with suspected STEMI", "source_id": "esc-2023-sca"}], "strength": "forte", "condition": "Suspicion de STEMI"}]}, "sources": [{"id": "esc-2023-sca", "url": "https://doi.org/10.1093/eurheartj/ehad191", "title": "2023 ESC Guidelines for the management of acute coronary syndromes", "citation": "Byrne RA et al. Eur Heart J 2023;44:3720-3826", "accessed_at": null, "page_offset": -3719, "organisation": "ESC", "publication_date": null}, {"id": "rms-2024-sca", "url": "https://doi.org/10.53738/REVMED.2024.20.875.1026", "title": "Prise en charge du syndrome coronarien aigu. Recommandations 2023 de la Société européenne de cardiologie", "citation": "Planchat A et al. Rev Med Suisse 2024;20:1026-31", "accessed_at": null, "page_offset": -1024, "organisation": "Revue Médicale Suisse", "publication_date": null}], "refer_follow": {"refer": [{"id": "ref-1", "urgency": "urgent", "criteria": "Suspicion de STEMI", "evidence": [{"page": 3745, "quote": "It is recommended that EMS transfer patients with suspected STEMI to a PCI-capable centre, bypassing non-PCI centres.", "source_id": "esc-2023-sca"}], "strength": "forte", "destination": "Centre de cardiologie interventionnelle, directement (sans passer par un centre sans salle de cathétérisme)"}, {"id": "ref-2", "urgency": "urgent", "criteria": "Après fibrinolyse : immédiatement si échec, dans les 2 à 24 h si réponse", "evidence": [{"page": 1027, "quote": "soit immédiatement en cas d'échec de la fibrinolyse soit dans les 2 à 24 heures en cas de réponse à cette dernière", "source_id": "rms-2024-sca"}], "strength": null, "destination": "Centre de cardiologie interventionnelle"}], "follow_up": [{"id": "fu-1", "what": "Réadaptation cardiaque pour tous ; polypill de prévention secondaire pour l'observance", "when": "Dès la sortie", "evidence": [{"page": 3787, "quote": "It is recommended that all ACS patients participate in a medically supervised, structured, comprehensive, multidisciplinary exercise-based cardiac rehabilitation and prevention programme.", "source_id": "esc-2023-sca"}, {"page": 1030, "quote": "La « polypill » incluant les traitements de prévention secondaire recommandés entre dans les recommandations (classe IIa)", "source_id": "rms-2024-sca"}]}, {"id": "fu-2", "what": "Objectif LDL < 55 mg/dL (1,4 mmol/L) et baisse d'au moins 50 %", "when": "Bilan lipidique de contrôle", "evidence": [{"page": 3787, "quote": "It is recommended to aim to achieve an LDL-C level of <1.4 mmol/L (<55 mg/dL) and to reduce LDL-C by ≥50% from baseline.", "source_id": "esc-2023-sca"}]}, {"id": "fu-3", "what": "Aspirine seule par défaut", "when": "Après 12 mois", "evidence": [{"page": 1030, "quote": "Le traitement antithrombotique à long terme (après 12 mois) par défaut reste l'aspirine en monothérapie", "source_id": "rms-2024-sca"}]}]}, "schema_version": "1.1.0"}$fiche$::jsonb, now())
  on conflict (subject_id, version) do nothing;

insert into subjects (id, title, template, specialite) values ('diabete-type-2', 'Diabète de type 2 de l''adulte', 'pathologie', 'endocrinologie')
  on conflict (id) do nothing;
insert into fiche_versions (subject_id, version, content, published_at) values ('diabete-type-2', 1, $fiche${"meta": {"id": "diabete-type-2", "title": "Diabète de type 2 de l'adulte", "motifs": ["diabète de type 2", "hyperglycémie", "Ramadan", "hypoglycémie"], "status": "published", "country": "DZ", "version": "1.2.3", "audience": ["MG"], "language": "fr", "template": "pathologie", "specialite": "endocrinologie", "next_review_at": null, "last_reviewed_at": "2026-10-22"}, "scope": {"exclusions": ["Diabète gestationnel"], "population": "Adulte vivant avec un diabète de type 2, prise en charge en 1re, 2e et 3e ligne"}, "treat": {"do_not": [{"id": "dt2-036", "refs": [], "text": "Ne pas associer deux médicaments de même mécanisme d'action.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 19, "quote": "Il est recommandé de ne pas associer deux médicaments de même mécanisme d’action", "source_id": "has-dt2-2024"}, {"page": 38, "quote": "il ne faut jamais associer entre eux les médicaments d’une même classe.", "source_id": "dz-guide-diabeto-2015"}], "strength": null, "condition": null}, {"id": "dt2-037", "refs": [], "text": "Ne pas associer aGLP1 et iDPP4.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 23, "quote": "Il n’y a pas lieu d’associer GLP1 et iDPP4", "source_id": "has-dt2-2024"}], "strength": null, "condition": null}, {"id": "dt2-035", "refs": [], "text": "aGLP1 à éviter en cas d'insuffisance cardiaque instable ou d'hospitalisation pour insuffisance cardiaque.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 32, "quote": "En cas d’intolérance ou de contre-indication, les aGLP-1 sont une alternative aux iSGLT2 en association avec la metformine, mais doivent être évités en cas d’insuffisance cardiaque instable ou d’hospitalisation pour insuffisance cardiaque", "source_id": "has-dt2-2024"}], "strength": "forte", "condition": "insuffisance cardiaque instable"}, {"id": "dt2-038", "refs": [], "text": "Les sulfamides en bithérapie avec la metformine ne sont plus la stratégie préférentielle (hypoglycémies sévères).", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 21, "quote": "La prescription des sulfamides hypoglycémiants en bithérapie en association avec MET n’est plus la stratégie préférentielle recommandée", "source_id": "has-dt2-2024"}], "strength": null, "condition": null}, {"id": "dt2-039", "refs": [], "text": "Chez les plus âgés, ne pas instaurer de sulfamides (surtout à longue durée d'action) s'il existe une alternative.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 29, "quote": "l’instauration des sulfamides, en particulier ceux à longue durée d’action, chez les personnes les plus âgées n’est pas recommandée", "source_id": "has-dt2-2024"}, {"page": 34, "quote": "Eviter les sulfonylurées à action prolongée (voir Tableau) chez les patients âgés et les remplacer par des sulfonylurées à action courte.", "source_id": "dz-guide-diabeto-2015"}], "strength": null, "condition": "personne âgée, alternative disponible"}, {"id": "dt2-040", "refs": [], "text": "Chez la personne âgée fragile, pas de régime restrictif (risque de dénutrition et de sarcopénie).", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 15, "quote": "Les régimes de restriction quantitative ou qualitative sont fortement déconseillés chez les personnes à risque de dénutrition et de sarcopénie, en particulier chez les personnes âgées en situation de fragilité.", "source_id": "has-dt2-2024"}], "strength": null, "condition": "personne âgée fragile"}], "actions": [{"id": "dt2-001", "refs": [], "text": "Les modifications thérapeutiques du mode de vie (MTMV) sont indispensables à toutes les étapes.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 9, "quote": "La mise en place de mesures efficaces de modification thérapeutique du mode de vie (MTMV) est indispensable à la prise en charge du patient vivant avec un DT2", "source_id": "has-dt2-2024"}, {"page": 32, "quote": "Il est indispensable et doit toujours être mis en place en première approche dans le diabète de type 2.", "source_id": "dz-guide-diabeto-2015"}], "strength": "modérée", "condition": null}, {"id": "dt2-030", "refs": [], "text": "Démarrer aux doses minimales puis augmenter progressivement jusqu'à la dose maximale tolérée ou l'objectif.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 19, "quote": "les traitements seront démarrés aux doses minimales recommandées qui seront augmentées progressivement jusqu’aux doses maximales tolérées ou jusqu’à l’atteinte de l’objectif", "source_id": "has-dt2-2024"}], "strength": null, "condition": null}, {"id": "dt2-031", "refs": [], "text": "Dépistage et prise en charge de tous les facteurs de risque cardiovasculaire : tabac, HTA, sédentarité, obésité, dyslipidémie.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 9, "quote": "La prise en charge globale devrait inclure le dépistage et la prise en charge de tous les facteurs de risque cardiovasculaire, notamment : tabac, hypertension artérielle, sédentarité, obésité, dyslipidémie, etc.", "source_id": "has-dt2-2024"}], "strength": "forte", "condition": null}, {"id": "dt2-032", "refs": [], "text": "Activité physique adaptée : programme d'endurance et de renforcement de 3 mois renouvelable, 2 à 3 séances par semaine.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 13, "quote": "Prescrire un programme d’AP adaptée d’endurance et de renforcement musculaire, d’une durée de 3 mois, renouvelable, à raison de 2 à 3 séances par semaine", "source_id": "has-dt2-2024"}], "strength": null, "condition": null}, {"id": "dt2-033", "refs": [], "text": "Patient en surpoids ou obèse : une perte de 5 % du poids améliore significativement l'équilibre métabolique.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 14, "quote": "Une perte de 5 % du poids ou plus au diagnostic permet une amélioration métabolique significative (glycémique, lipidique, tensionnelle)", "source_id": "has-dt2-2024"}], "strength": null, "condition": "surpoids ou obésité"}, {"id": "dt2-034", "refs": [], "text": "Avant un iSGLT2 : évaluer le risque d'acidocétose (épisodes antérieurs, maladie intercurrente, régime très pauvre en glucides ou cétogène).", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 21, "quote": "À l’initiation du traitement avec un iSGLT2, il est recommandé d’évaluer le risque d’acidocétoses diabétiques (ex. : récurrence d’épisode, maladie intercurrente, régime très faible en glucides ou cétogène)", "source_id": "has-dt2-2024"}], "strength": "faible", "condition": "initiation d'un iSGLT2"}, {"id": "dz-007", "refs": [], "text": "Hypoglycémie légère : 15 g de sucre, contrôler 15 min après, resucrer si besoin, puis sucres complexes (pain, biscuits).", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 46, "quote": "Si l’hypoglycémie est légère, donner 15 grammes de sucre, contrôler 15mn après, si l’hypoglycémie persiste, resucrer encore avec 15 g de sucre, si la glycémie est jugulée, passer au sucres complexes, comme le pain ou les biscuits.", "source_id": "dz-guide-diabeto-2015"}], "strength": null, "condition": "hypoglycémie légère"}], "medications": [{"id": "med-metformine", "inn": "metformine", "dose": 500, "phase": "initiation", "route": "orale", "missing": ["duration"], "duration": null, "evidence": [{"page": 35, "quote": "chlorhydrate de metformine 1 à 3 comp / j (2 g/j)", "source_id": "dz-guide-diabeto-2015"}, {"page": 35, "quote": "chlorhydrate de metformine 500 mg, 850 mg, 1000 mg", "source_id": "dz-guide-diabeto-2015"}, {"page": 35, "quote": "Commencer par la dose la plus faible pour minimiser les effets secondaires digestifs et favoriser l’observance.", "source_id": "dz-guide-diabeto-2015"}, {"page": 35, "quote": "Utiliser avec prudence chez les sujets âgés à cause de l’insuffisance rénale", "source_id": "dz-guide-diabeto-2015"}, {"page": 35, "quote": "Suspendre le traitement pendant 48-72h le jour où le patient subit des examens radiologiques avec produits de contraste et avant toute anesthésie générale et ne le reprendre qu’après reprise d’une diurèse normale.", "source_id": "dz-guide-diabeto-2015"}, {"page": 35, "quote": "principalement due à une administration inappropriée chez des patients présentant une dysfonction hépatique/ rénale/myocardique", "source_id": "dz-guide-diabeto-2015"}, {"page": 34, "quote": "IV.3.3.1 Les antidiabétiques oraux", "source_id": "dz-guide-diabeto-2015"}, {"page": 20, "quote": "La metformine reste à ce jour le traitement recommandé en 1re intention en raison de son ancienneté, de son faible coût, de son profil de tolérance ainsi que de ses effets sur l’HbA1c", "source_id": "has-dt2-2024"}], "max_dose": "2 g/j", "strength": null, "condition": "en 1re intention, sauf contre-indication ou intolérance", "dose_unit": "mg", "frequency": "1 à 3 comprimés par jour", "dose_basis": "fixe", "prescriber": null, "adjustments": ["Commencer par la dose la plus faible (troubles digestifs)", "Prudence chez le sujet âgé (fonction rénale)", "Suspendre 48 à 72 h lors d'un examen avec produit de contraste ou avant anesthésie générale ; reprendre après reprise d'une diurèse normale"], "alternative_group": null, "contraindications": ["Dysfonction hépatique, rénale ou myocardique (risque d'acidose lactique)"], "local_availability": {"brands": [], "status": null, "country": "DZ"}}, {"id": "med-liraglutide", "inn": "liraglutide", "dose": 1.2, "phase": null, "route": "sous-cutanée", "missing": ["contraindications", "duration", "phase"], "duration": null, "evidence": [{"page": 37, "quote": "Le Liraglutide est le premier analogue du GLP-1 humain (homologie de 97%) en une injection S/C par jour (aux posologies de 1.2 ou 1.8 mg).", "source_id": "dz-guide-diabeto-2015"}, {"page": 37, "quote": "liraglutide 12-15 h 1.2-1.8 mg", "source_id": "dz-guide-diabeto-2015"}, {"page": 21, "quote": "La présence d’un antécédent de maladie cardiovasculaire doit faire envisager et idéalement proposer un traitement par iSGLT2 ou aGLP1, indépendamment de l’HbA1c et d’un traitement par metformine", "source_id": "has-dt2-2024"}, {"page": 22, "quote": "l’ajout d’un iSGLT2 ou d’un aGLP1 est recommandé chez les patients en prévention primaire à haut niveau de risque cardiovasculaire", "source_id": "has-dt2-2024"}, {"page": 22, "quote": "il est recommandé l’ajout de aGLP1 à dose antidiabétique, si présence obésité (IMC > ou égale à 30 kg/m2)", "source_id": "has-dt2-2024"}], "max_dose": "1,8 mg/j", "strength": null, "condition": "antécédent de maladie cardiovasculaire, haut risque cardiovasculaire, ou obésité (IMC ≥ 30 kg/m²), en ajout à la metformine", "dose_unit": "mg", "frequency": "1 injection par jour", "dose_basis": "fixe", "prescriber": null, "adjustments": [], "alternative_group": null, "contraindications": [], "local_availability": {"brands": [], "status": null, "country": "DZ"}}, {"id": "med-sitagliptine", "inn": "sitagliptine", "dose": 100, "phase": null, "route": "orale", "missing": ["contraindications", "duration", "max_dose", "phase"], "duration": null, "evidence": [{"page": 36, "quote": "sitagliptine 100 mg 12.4 h 100 mg 1x/jour", "source_id": "dz-guide-diabeto-2015"}, {"page": 34, "quote": "IV.3.3.1 Les antidiabétiques oraux", "source_id": "dz-guide-diabeto-2015"}, {"page": 22, "quote": "un iDPP4, option la plus simple pour la pratique clinique", "source_id": "has-dt2-2024"}, {"page": 20, "quote": "iDPP4, option la plus simple pour la pratique clinique en l’absence d’insuffisance cardiaque, de maladie cardiovasculaire artérioscléreuse établie, de néphropathie diabétique ou d’un haut risque cardiovasculaire", "source_id": "has-dt2-2024"}, {"page": 29, "quote": "En cas de contre-indication ou de mauvaise tolérance à la MET, les iDPP4 peuvent être l’alternative à privilégier c