insert into fiche_versions (subject_id, version, content, published_at) values ('stroke', 1, $fiche${"meta": {"id": "stroke", "title": "Accident vasculaire cérébral : reconnaître et orienter en urgence", "motifs": [], "status": "published", "country": "DZ", "version": "1.0.0", "audience": ["urgences"], "language": "fr", "template": "urgence", "specialite": "Neurologie", "next_review_at": null, "last_reviewed_at": "2026-10-17"}, "scope": {"exclusions": [], "population": "Adulte avec suspicion d'AVC ou d'AIT, de l'alerte à la phase hospitalière initiale"}, "treat": {"do_not": [{"id": "avc-029", "refs": [], "text": "N'appelez pas d'abord le médecin traitant : appelez directement le SAMU.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 21, "quote": "l'appel au médecin traitant est à éviter", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-030", "refs": [], "text": "Ne vous rassurez pas devant des symptômes transitoires.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 20, "quote": "Les symptômes transitoires durant quelques minutes ou heures sont faussement rassurants", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "actions": [{"id": "avc-018", "refs": [], "text": "Posez une voie veineuse périphérique.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 31, "quote": "la pose d'une voie veineuse périphérique", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-027", "refs": [], "text": "Thrombolyse IV le plus tôt possible : délai cible < 60 min après l'arrivée.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 34, "quote": "Le temps médian cible entre l'arrivée dans l'établissement et le traitement médical d'urgence est de moins de 60 min.", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-028", "refs": [], "text": "Pour les indications de la thrombolyse IV, reportez-vous aux recommandations HAS.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 34, "quote": "En ce qui concerne les indications de la thrombolyse IV, se reporter aux recommandations HAS", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-033", "refs": [], "text": "Surveillez température, PA, fréquence cardiaque, saturation, glycémie capillaire, diurèse et transit.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 41, "quote": "Les constantes à surveiller sont : la température, la PA, la fréquence cardiaque, la saturation en oxygène, la glycémie capillaire.", "source_id": "has-2025-avc-parcours"}, {"page": 41, "quote": "La diurèse et le transit sont également surveillés.", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-034", "refs": [], "text": "Surveillez l'état neurologique ; signalez immédiatement toute aggravation au médecin.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 41, "quote": "toute aggravation est notifiée immédiatement au médecin", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-035", "refs": [], "text": "Prévention secondaire : antiagrégant plaquettaire, aspirine et/ou clopidogrel.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 47, "quote": "Le traitement antithrombotique repose sur une anti-agrégation plaquettaire par aspirine et/ou clopidogrel.", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": "AVC ischémique d'origine athéromateuse"}, {"id": "avc-036", "refs": [], "text": "Prévention secondaire : anticoagulant oral (AVK ou AOD) au long cours, même en cas de retour en rythme sinusal.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 47, "quote": "la prévention cardio-embolique repose sur les anticoagulants oraux (antivitamine K (AVK) ou anticoagulants oraux directs (AOD)), à maintenir au long cours, même en cas de retour en rythme sinusal", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": "Fibrillation auriculaire non valvulaire"}], "medications": []}, "advise": [], "assess": {"ask": [{"id": "avc-014", "refs": [], "text": "Demandez la date et l'heure exactes du début des symptômes ; à défaut, l'heure où le patient a été vu pour la dernière fois sans symptôme.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 25, "quote": "Date et heure exactes de début des symptômes", "source_id": "has-2025-avc-parcours"}, {"page": 25, "quote": "Date et heure auxquelles le patient a été vu pour la dernière fois sans symptôme", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-015", "refs": [], "text": "Demandez s'il prend un anticoagulant : molécule, date et heure de la dernière prise.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 25, "quote": "Prise de traitements antithrombotiques et particulièrement anticoagulants", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "tests": [{"id": "avc-017", "refs": [], "text": "Faites une glycémie capillaire, une hémostase, un hémogramme avec plaquettes.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 31, "quote": "hémostase, hémogramme et plaquettes et glycémie capillaire", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-019", "refs": [], "text": "Faites un ECG si cela ne retarde pas la prise en charge.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 31, "quote": "la réalisation d'un électrocardiogramme (ECG) (si cela ne génère pas une perte de temps)", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-024", "refs": [], "text": "Imagerie cérébrale en urgence : délai cible < 25 min après l'arrivée.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 32, "quote": "Le temps médian cible entre l'arrivée dans l'établissement et l'imagerie est de moins de 25 minutes", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-025", "refs": [], "text": "Privilégiez l'IRM cérébrale au scanner.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 32, "quote": "Il est conseillé de privilégier l'IRM cérébrale par rapport au scanner cérébral", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "examine": [{"id": "avc-011", "refs": [], "text": "Faites le test FAST (VITE) : faites sourire, faites lever les deux bras, faites répéter une phrase simple.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 21, "quote": "Demander à la personne de sourire", "source_id": "has-2025-avc-parcours"}, {"page": 21, "quote": "Demander à la personne de lever les deux bras", "source_id": "has-2025-avc-parcours"}, {"page": 21, "quote": "Demander à la personne de répéter une phrase simple", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-013", "refs": [], "text": "Évaluez la gravité par le score NIHSS.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 25, "quote": "Signes de gravité : score de sévérité clinique NIHSS", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-016", "refs": [], "text": "Prenez les constantes : PA, fréquence cardiaque, saturation, température ; posez un monitoring.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 31, "quote": "la prise de constantes : pression artérielle (PA), fréquence cardiaque, saturation en oxygène, température (et pose d'un monitoring)", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "pathway": {"nodes": [{"id": "n1", "type": "decision", "items": [], "branches": [{"id": "n1-b1", "label": "Moins de 4 h 30", "next_node_id": "n2"}, {"id": "n1-b2", "label": "4 h 30 à 24 h", "next_node_id": "n3"}, {"id": "n1-b3", "label": "Heure inconnue ou symptômes au réveil", "next_node_id": "n4"}, {"id": "n1-b4", "label": "Plus de 24 h", "next_node_id": "n5"}], "question": "Délai depuis le début des symptômes ?"}, {"id": "n2", "type": "end", "items": [{"id": "avc-020", "refs": [], "text": "Thrombolyse IV et/ou thrombectomie possibles dans les 4 h 30 : orientez sans délai.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 32, "quote": "Théoriquement, le patient peut bénéficier d'une thrombolyse IV et/ou d'une TM dans les 4 h 30 après le début des symptômes.", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "branches": [], "question": "Moins de 4 h 30"}, {"id": "n3", "type": "end", "items": [{"id": "avc-021", "refs": [], "text": "Thrombolyse IV possible jusqu'à 9 h, thrombectomie jusqu'à 24 h ; imagerie de perfusion impérative entre 4 h 30 et 9 h.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 33, "quote": "peut bénéficier d'une thrombolyse IV jusqu'à 9 h ou d'une TM jusqu'à 24 h après le début des symptômes", "source_id": "has-2025-avc-parcours"}, {"page": 33, "quote": "imagerie de perfusion impérative si le patient est exploré entre 4 h 30 et 9 h après le début des symptômes", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "branches": [], "question": "4 h 30 à 24 h"}, {"id": "n4", "type": "end", "items": [{"id": "avc-022", "refs": [], "text": "Thrombolyse IV possible si le délai calculé est inférieur à 9 h, sous réserve de l'imagerie cérébrale.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 33, "quote": "est inférieur à 9 h (sous réserve de l'imagerie cérébrale)", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "branches": [], "question": "Heure inconnue ou symptômes au réveil"}, {"id": "n5", "type": "end", "items": [{"id": "avc-023", "refs": [], "text": "Plus de reperfusion possible ; imagerie rapide quand même, pour confirmer le diagnostic et prévenir la récidive.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 34, "quote": "Plus de 24 h après le début des symptômes, le patient ne peut plus bénéficier, à l'heure actuelle, d'un traitement de reperfusion", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}], "branches": [], "question": "Plus de 24 h"}], "start_node_id": "n1"}}, "review": {"reviewer": "Mounib Zaidi", "change_log": [{"by": "Claude (conversion)", "date": "2026-10-17", "summary": "Conversion de la fiche v1 (schéma numéroté) en v1.1, citations vérifiées sur le PDF HAS. Retirés : renvoi à la fiche avc-thrombolyse (inexistante), ligne altéplase / ténectéplase (aucune dose dans la source), définitions et doublons de l'essentiel."}, {"by": "Mounib Zaidi", "date": "2026-10-17", "summary": "Validation clinique et publication de la version v1.1."}], "reviewed_at": "2026-10-17", "clinical_approval": true, "unresolved_issues": []}, "red_box": {"signs": [{"id": "avc-004", "refs": [], "text": "Paralysie faciale : asymétrie du visage ou du sourire.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 20, "quote": "paralysie faciale : asymétrie du visage ou du sourire", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-005", "refs": [], "text": "Faiblesse d'un bras, d'une main, d'une jambe ou d'un hémicorps.", "basis": null, "origin": "source", "timing": null, "evidence": [{"page": 20, "quote": "hémiplégie : faiblesse d'un bras, d'une main, d'une jambe ou d'un hémicorps", "source_id": "has-2025-avc-parcours"}], "strength": null, "condition": null}, {"id": "avc-006", "refs": [], "text": "Trouble du langage : impossibilité de trouver les mots.", "basis": null, "origin": "source", "timing": null, "evidence": [